export const TEAM_ROLES_ACTIVITIES = [
{n:1,type:"mcq",micro:"Apa itu peran tim",q:"'Peran' dalam tim adalah...",options:["Bagian tugas & tanggung jawab tertentu yang dipegang seorang anggota","Nama panggilan anggota","Urutan tempat duduk"],answer:0,explain:"Peran menjelaskan 'kamu bertanggung jawab atas apa'. Peran yang jelas mencegah tugas terlewat atau dikerjakan ganda.",hint:"Bagian tanggung jawab tertentu, atau nama panggilan?"},
{n:2,type:"mcq",micro:"Kenapa peran jelas penting",q:"Kalau peran tidak dibagi jelas, sering terjadi...",options:["Tim jadi lebih akrab & kompak karena semua orang bebas mengerjakan apa saja yang mereka sukai kapan saja","Ada tugas yang tidak dikerjakan siapa pun ('kukira kamu') atau dikerjakan dua orang sekaligus","Semua tugas selesai lebih cepat karena tidak ada waktu terbuang untuk membahas siapa mengerjakan bagian yang mana"],answer:1,explain:"Tanpa kejelasan 'siapa bertanggung jawab atas ini', bagian penting bisa jatuh di celah.",hint:"Tugas terlewat/ganda, atau lebih cepat?"},
{n:3,type:"mcq",micro:"Jenis peran umum",q:"Selain 'pengerja tugas', tim sering butuh peran seperti...",options:["Hanya satu peran saja, yaitu pengerja tugas, karena peran lain seperti pencatat atau penjaga waktu tidak berguna bagi tim","Peran hiasan tanpa fungsi yang sekadar membuat nama jabatan terdengar keren, tetapi tidak mengubah cara tim bekerja","Koordinator, pencatat, pengecek kualitas, penjaga waktu, penghubung/komunikasi"],answer:2,explain:"Peran-peran pendukung ini menjaga tim tetap terorganisasi. Kadang satu orang memegang beberapa.",hint:"Beberapa peran fungsional, atau cuma pengerja?"},
{n:4,type:"mcq",micro:"Mencocokkan peran dengan kekuatan",q:"Cara membagi peran yang membuat tim efektif:",options:["Cocokkan dengan kekuatan & minat tiap orang, tapi beri kesempatan belajar hal baru juga","Undi acak tanpa melihat kemampuan & minat siapa pun, supaya semua orang pasti kebagian apa saja yang keluar dari undian","Beri semua peran penting ke satu orang yang paling pintar, sedangkan anggota lain cukup mengerjakan hal-hal kecil saja"],answer:0,explain:"Peran yang cocok = kerja lebih cepat & hasil lebih baik. Tapi tim juga tempat belajar, jadi rotasi peran sesekali berguna.",hint:"Cocokkan kekuatan (+ belajar), atau undi acak?"},
{n:5,type:"mcq",micro:"Tanggung jawab yang jelas",q:"'Kamu yang urus konsumsi' masih kurang jelas. Versi yang lebih jelas:",options:["'Konsumsi diurus ya, pokoknya jangan sampai kurang & jangan terlambat, nanti kita lihat saja bagaimana jadinya.'","'Kamu belanja & siapkan 30 kotak makan + air, selesai sebelum jam 8, anggaran Rp X'","'Kamu yang tanggung jawab soal makanan pokoknya, terserah kamu mau bagaimana caranya & kapan menyelesaikannya.'"],answer:1,explain:"Tanggung jawab yang jelas menyebut apa, berapa, kapan, & batasannya. 'Urus' saja terlalu kabur.",hint:"Apa+berapa+kapan+batas, atau 'urus ya'?"},
{n:6,type:"mcq",micro:"Peran vs melakukan segalanya",q:"Punya peran berarti kamu fokus pada tanggung jawabmu, TAPI dalam tim yang baik kamu juga...",options:["Tidak pernah menyentuh apa pun di luar perannya, sekalipun ada teman yang kewalahan & tim hampir kehabisan waktu","Mengambil alih peran orang lain tanpa bilang-bilang, karena kamu merasa caramu pasti lebih baik daripada caranya","Membantu di luar peranmu saat ada yang butuh atau saat tim mepet waktu"],answer:2,explain:"Peran memberi kejelasan; kesediaan membantu di luar peran memberi ketahanan.",hint:"Bantu bila perlu, atau kaku 'bukan peranku'?"},
{n:7,type:"mcq",micro:"Peran pencatat",q:"Peran 'pencatat' (notulen) dalam rapat tim berguna untuk...",options:["Mencatat keputusan, tugas baru, & siapa mengerjakan apa, lalu membagikannya ke semua","Menulis semua kata yang diucapkan","Tidak ada gunanya"],answer:0,explain:"Tanpa catatan, keputusan rapat mudah terlupa atau diingat berbeda-beda. Pencatat menjaga acuan bersama.",hint:"Merangkum keputusan & tugas, atau transkrip lengkap?"},
{n:8,type:"mcq",micro:"Peran penjaga waktu",q:"Peran 'penjaga waktu' saat rapat atau saat mengerjakan tugas berkelompok:",options:["Menghentikan orang di tengah kalimat dengan keras kapan pun waktu terasa habis, tanpa peduli ide mereka sudah selesai atau belum","Mengingatkan tim soal sisa waktu supaya semua agenda/tugas sempat dibahas/dikerjakan","Memaksa semua orang bicara cepat-cepat & mengebut tiap agenda supaya rapat selesai, walau tidak semua hal sempat dipahami"],answer:1,explain:"Penjaga waktu membantu tim tidak menghabiskan seluruh waktu pada satu hal & kehabisan waktu untuk yang lain.",hint:"Mengingatkan sisa waktu dengan sopan, atau memaksa / memotong?"},
{n:9,type:"order",micro:"Membagi peran di awal proyek",q:"Urutkan langkah membagi peran tim di awal proyek.",items:["Daftar semua pekerjaan & tanggung jawab yang dibutuhkan proyek","Tanyakan kekuatan, minat, & ketersediaan tiap anggota","Cocokkan peran dengan orang, seimbangkan beban","Tuliskan: siapa memegang peran apa & tanggung jawabnya persis apa"],answer:[0,1,2,3],explain:"Daftar pekerjaan → kenali anggota → cocokkan & seimbangkan → tuliskan. Kejelasan tertulis mengunci kesepakatan.",hint:"Apa yang didaftar sebelum mencocokkan orang?"},
{n:10,type:"mcq",micro:"Peran koordinator bukan bos",q:"Peran koordinator/ketua yang baik:",options:["Memerintah & menyuruh-nyuruh anggota sesuka hati, mengambil semua keputusan sendiri, & jarang mau mendengarkan masukan dari tim","Tidak berbuat apa-apa sama sekali, membiarkan anggota bingung sendiri tentang tugasnya, & hanya muncul saat tim menerima nilai bagus","Menjaga tim tetap selaras & bergerak, memastikan semua terlibat & tahu tugasnya — bukan mengambil semua keputusan sendiri"],answer:2,explain:"Koordinator memfasilitasi. Ia melayani tim, bukan memerintahnya.",hint:"Menyelaraskan & memastikan semua terlibat, atau memerintah / diam?"},
{n:11,type:"tf",micro:"Peran jelas mencegah kebingungan",q:"Benar atau Salah: Menuliskan siapa bertanggung jawab atas apa di awal proyek mengurangi kebingungan & tugas yang terlewat di kemudian hari.",answer:true,explain:"'Kukira kamu yang kerjakan' hampir selalu berasal dari peran yang tidak pernah dibuat jelas.",hint:"Kejelasan peran mencegah kebingungan, atau tak berpengaruh?"},
{n:12,type:"tf",micro:"Satu orang semua peran",q:"Benar atau Salah: Cara terbaik menjalankan tim adalah memberikan semua peran penting (koordinator, pengecek, pencatat, pengerja utama) kepada satu orang yang paling mampu.",answer:false,explain:"Sebaliknya, itu membebani satu orang & membuat yang lain pasif serta tidak belajar. Peran sebaiknya tersebar sesuai kekuatan.",hint:"Semua ke satu orang, atau tersebar?"},
{n:13,type:"mcq",micro:"Peran pengecek kualitas",q:"Peran 'pengecek kualitas' (quality control):",options:["Meninjau hasil sebelum dikumpulkan: apakah lengkap, sesuai instruksi, & rapi — lalu memberi umpan balik","Mengerjakan ulang semua bagian milik orang lain agar hasilnya sempurna menurutmu, tanpa memberi tahu mereka apa yang diperbaiki","Hanya memuji semua bagian supaya suasana tetap senang, tanpa benar-benar memeriksa apakah hasilnya lengkap & sesuai instruksi"],answer:0,explain:"Satu pasang mata yang khusus mengecek keseluruhan menangkap kesalahan yang si pembuat lewatkan.",hint:"Meninjau & beri umpan balik, atau mengerjakan ulang / hanya memuji?"},
{n:14,type:"mcq",micro:"Menerima peran yang bukan favorit",q:"Kamu diberi peran yang kurang kamu sukai tapi tim butuh. Sikap:",options:["Mengerjakan asal-asalan sebagai bentuk protes, supaya tim sadar bahwa kamu tidak cocok & akhirnya menukar perannya untukmu, tanpa perlu bicara","Sampaikan preferensimu sekali; kalau tim tetap butuh kamu di situ, jalani dengan baik — kadang tim butuh kamu di tempat tertentu","Menolak mentah-mentah & tidak mengerjakannya sama sekali, karena menurutmu peran yang tidak kamu sukai bukan tanggung jawabmu"],answer:1,explain:"Menyuarakan preferensi itu wajar, tapi mendukung kebutuhan tim (dalam batas wajar) adalah bagian dari kerja sama.",hint:"Suarakan lalu jalani baik, atau tolak / asal-asalan?"},
{n:15,type:"mcq",micro:"Peran penghubung",q:"Peran 'penghubung' (komunikasi) dalam tim yang berurusan dengan pihak luar (guru, panitia lain):",options:["Semua orang menghubungi pihak luar sendiri-sendiri kapan pun mau, sehingga guru & panitia menerima banyak pesan berbeda dari kelompok yang sama","Tidak ada yang menghubungi pihak luar sama sekali, & tim menunggu saja sampai mereka datang sendiri membawa kabar penting yang dibutuhkan","Menjadi satu titik kontak yang menyampaikan & menerima info, lalu meneruskan ke tim — supaya pesan tidak simpang siur"],answer:2,explain:"Satu penghubung mencegah pihak luar menerima info berbeda dari anggota berbeda.",hint:"Satu titik kontak, atau semua sendiri-sendiri?"},
{n:16,type:"mcq",micro:"Tanggung jawab & akuntabilitas",q:"'Bertanggung jawab atas suatu peran' berarti...",options:["Kalau bagian itu bermasalah, kamu yang pertama menindaklanjuti & mengabari tim — bukan menunggu disuruh","Kamu boleh menyalahkan orang lain kalau bagianmu gagal, selama kamu sudah menyebut bahwa kamu sebenarnya sudah berusaha keras","Kamu hanya bekerja kalau diingatkan terus-menerus oleh ketua, sebab tanggung jawab itu baru muncul setelah ada yang menagih"],answer:0,explain:"Akuntabilitas: kamu memegang bagian itu, jadi kamu yang memastikannya beres & memberi kabar bila ada masalah.",hint:"Kamu yang memastikan & mengabari, atau menunggu disuruh?"},
{n:17,type:"mcq",micro:"Rotasi peran",q:"Merotasi peran antar proyek (mis. yang tadinya koordinator jadi pengecek) berguna karena...",options:["Tidak ada gunanya sama sekali, sebab peran harus tetap sama selamanya supaya tiap orang jadi ahli di satu hal saja","Semua anggota belajar berbagai keterampilan & lebih memahami peran satu sama lain","Membuat tim bingung selamanya, karena tiap orang jadi tidak tahu bagiannya & selalu harus mulai belajar dari nol lagi"],answer:1,explain:"Rotasi membuat tim lebih tangguh (banyak orang bisa banyak peran) & menumbuhkan empati antar peran.",hint:"Semua belajar & saling paham, atau membingungkan?"},
{n:18,type:"mcq",micro:"Peran & beban seimbang",q:"Setelah membagi peran, hal yang perlu dicek:",options:["Siapa yang punya peran dengan nama paling keren","Tidak perlu dicek","Apakah beban tiap peran kira-kira seimbang? Ada yang kelebihan atau kekurangan?"],answer:2,explain:"Peran bisa terdengar setara tapi bebannya jauh berbeda. Cek & sesuaikan agar adil.",hint:"Cek keseimbangan beban, atau nama peran?"},
{n:19,type:"mcq",micro:"Semua peran penting",q:"Dalam tim, peran 'di belakang layar' (mencari data, merapikan, mencatat) dibanding peran 'tampil' (presentasi):",options:["Sama-sama penting; hasil bagus butuh keduanya","Kurang penting daripada peran yang tampil, karena hasil akhir hanya dinilai dari presentasi yang dilihat oleh banyak orang","Tidak dihitung sebagai kontribusi sama sekali, karena pekerjaan yang tidak terlihat orang lain bukanlah bagian dari kerja tim"],answer:0,explain:"Presentasi hebat tidak berarti apa-apa tanpa isi & persiapan di belakangnya. Hargai semua peran.",hint:"Sama penting, atau kurang penting?"},
{n:20,type:"open",micro:"Membagi peran untuk sebuah tim",q:"Tim 5 orang mengerjakan proyek membuat video dokumenter pendek tentang lingkungan sekolah. Sebutkan peran-peran yang menurutmu dibutuhkan, tanggung jawab tiap peran secara spesifik, dan bagaimana kamu memastikan bebannya seimbang.",explain:"Jawaban baik menyebut peran yang masuk akal untuk proyek video (koordinator, peneliti/penulis naskah, juru kamera, editor, penghubung/narator) dengan tanggung jawab SPESIFIK tiap peran, dan menjelaskan cara menyeimbangkan beban (perkiraan jam, menggeser tugas dari peran berat, tenggat bertahap, cek kemajuan untuk menyeimbangkan ulang).",hint:"Daftar peran yang cocok untuk video; beri tiap peran tanggung jawab spesifik; lalu jelaskan cara cek & seimbangkan beban (perkiraan jam, tahapan, geser tugas).",sample:"Peran yang dibutuhkan: (1) Koordinator/sutradara: menyusun jadwal, memastikan semua bagian nyambung dengan pesan video, memimpin rapat, mengecek kemajuan tiap orang. (2) Peneliti & penulis naskah: mengumpulkan fakta soal lingkungan sekolah (data sampah, penghijauan), menyusun alur cerita & narasi, menyiapkan daftar pertanyaan wawancara. (3) Juru kamera & pengambil gambar: merekam lokasi, wawancara, dan b-roll sesuai daftar dari naskah; memastikan kualitas gambar & suara. (4) Editor: menggabungkan rekaman, menambah teks/subtitle & musik, menyesuaikan durasi. (5) Penghubung & narator: menghubungi narasumber (petugas kebersihan, guru, kepala sekolah) untuk izin & jadwal wawancara, dan mengisi suara narasi. Memastikan beban seimbang: setelah membagi, kami perkirakan bersama berapa jam kira-kira tiap peran, lalu geser tugas kecil bila ada yang jelas kelebihan (mis. editor biasanya berat, jadi ia dibebaskan dari tugas riset; koordinator ikut membantu penghubung). Kami juga sepakati tenggat per tahap (riset & naskah dulu, lalu syuting, lalu edit) supaya kerja tidak menumpuk di satu orang di waktu yang sama, dan cek kemajuan tiap 3 hari untuk menyeimbangkan ulang bila perlu."},
{n:21,type:"classify",micro:"Peran & tugasnya",q:"Cocokkan tiap tugas ke peran yang paling tepat: 'Koordinator', 'Pengecek kualitas', 'Pencatat', atau 'Penghubung'.",items:["Merangkum keputusan rapat & membagikannya","Meninjau draf akhir apakah sesuai instruksi","Menghubungi guru untuk menanyakan kriteria penilaian","Mengatur jadwal & mengingatkan tenggat tiap anggota"],groups:["Koordinator","Pengecek kualitas","Pencatat","Penghubung"],answer:{"Koordinator":["Mengatur jadwal & mengingatkan tenggat tiap anggota"],"Pengecek kualitas":["Meninjau draf akhir apakah sesuai instruksi"],"Pencatat":["Merangkum keputusan rapat & membagikannya"],"Penghubung":["Menghubungi guru untuk menanyakan kriteria penilaian"]},explain:"Tiap peran punya fokus: koordinator = alur & jadwal; pengecek = kualitas hasil; pencatat = catatan keputusan; penghubung = komunikasi ke luar.",hint:"Tugas ini paling cocok dipegang siapa?"},
{n:22,type:"mcq",micro:"Peran tumpang tindih",q:"Kalau dua anggota merasa sama-sama bertanggung jawab atas hal yang sama, sebaiknya...",options:["Batalkan bagian itu","Perjelas bersama: satu orang jadi penanggung jawab utama, satu jadi pendukung — bukan keduanya menganggap 'yang lain pasti kerjakan'","Biarkan, keduanya kerjakan"],answer:1,explain:"Tumpang tindih tanpa kejelasan sering berakhir dengan bagian itu TIDAK dikerjakan karena masing-masing menunggu.",hint:"Tunjuk satu penanggung jawab utama, atau biarkan ambigu?"},
{n:23,type:"mcq",micro:"Peran & kepercayaan",q:"Setelah peran dibagi, koordinator sebaiknya...",options:["Mengawasi & mengoreksi setiap langkah kecil yang dikerjakan anggota, tiap menit, supaya tidak ada satu pun kesalahan lolos begitu saja","Tidak pernah mengecek kemajuan sama sekali & menghilang sampai hari terakhir, karena percaya penuh bahwa semuanya pasti beres sendiri","Memercayai anggota mengerjakan perannya, sambil tetap mengecek kemajuan secara wajar — bukan mengawasi tiap menit atau menghilang total"],answer:2,explain:"Keseimbangan: percaya + cek berkala. Micromanaging melelahkan; menghilang berisiko.",hint:"Percaya + cek berkala, atau awasi ketat / hilang?"},
{n:24,type:"mcq",micro:"Ketika seseorang tidak cocok dengan perannya",q:"Seorang anggota kesulitan di perannya (mis. desain padahal ia tidak terbiasa). Sikap tim:",options:["Tinjau ulang: bisa dipasangkan dengan yang lebih ahli, ditukar peran, atau diberi bantuan & waktu belajar","Biarkan ia gagal sendirian sampai belajar dari kesalahannya, karena itu sudah perannya & tim tidak boleh ikut campur menolongnya","Ejek dia karena tidak bisa mendesain, supaya ia malu & berusaha lebih keras mempelajarinya sendiri tanpa bantuan siapa pun"],answer:0,explain:"Peran bukan hukuman. Kalau jelas tidak cocok, tim menyesuaikan — pasangkan, tukar, atau dukung.",hint:"Tinjau & sesuaikan, atau biarkan gagal / ejek?"},
{n:25,type:"mcq",micro:"Peran menjaga semangat",q:"Peran 'penyemangat' (yang menjaga suasana & mengapresiasi) dalam tim...",options:["Hanya untuk tim olahraga","Nyata & berharga — tim yang lelah & tegang bekerja lebih buruk; peran ini menjaga energi","Buang-buang orang"],answer:1,explain:"Suasana tim memengaruhi hasil. Seseorang yang sengaja menjaga semangat & mengakui usaha membuat perbedaan.",hint:"Nyata & berharga, atau buang orang?"},
{n:26,type:"mcq",micro:"Tanggung jawab bersama vs individu",q:"Dalam tim, tanggung jawab bekerja di dua tingkat:",options:["Hanya individu: urus bagianmu sendiri dengan baik & jangan pedulikan bagian atau kesulitan yang sedang dialami oleh anggota yang lain","Hanya bersama: yang penting hasil tim, sehingga tidak ada tanggung jawab pribadi untuk menepati bagian milik masing-masing anggota","Individu (menepati peranmu) DAN bersama (peduli pada hasil keseluruhan & membantu bila perlu)"],answer:2,explain:"Kamu bertanggung jawab pada kotakmu sendiri DAN pada gambar besarnya. Kedua tingkat itu berlaku sekaligus.",hint:"Dua tingkat sekaligus, atau salah satu?"},
{n:27,type:"tf",micro:"Peran bisa berubah",q:"Benar atau Salah: Sekali peran dibagi di awal proyek, tim tidak boleh mengubahnya lagi sampai proyek selesai, apa pun yang terjadi.",answer:false,explain:"Sebaliknya, peran adalah alat untuk kejelasan, bukan aturan kaku. Bila situasi berubah (ada yang sakit, satu bagian jadi jauh lebih berat), menyesuaikan peran adalah tanda tim yang responsif.",hint:"Peran kaku selamanya, atau bisa disesuaikan?"},
{n:28,type:"tf",micro:"Peran menghapus perlu komunikasi?",q:"Benar atau Salah: Setelah peran dibagi jelas, anggota tidak perlu lagi berkomunikasi — cukup masing-masing mengerjakan bagiannya sampai selesai.",answer:false,explain:"Sebaliknya, peran yang jelas mengurangi kebingungan, tapi tim tetap perlu update rutin & koordinasi agar bagian-bagian nyambung.",hint:"Peran menghapus perlu komunikasi, atau tetap perlu koordinasi?"},
{n:29,type:"mcq",micro:"Menilai peran koordinator",q:"Tanda koordinator melakukan perannya dengan baik:",options:["Semua anggota tahu tugas & tenggatnya, kemajuan terpantau, kendala tertangani lebih awal, & semua merasa didengar","Koordinator mengerjakan paling banyak tugas sendiri sampai kelelahan, sementara anggota lain hanya menunggu instruksi tanpa tahu gambaran besarnya","Tidak ada yang tahu apa yang terjadi kecuali koordinator, sebab semua informasi disimpan olehnya & anggota hanya diberi tahu seperlunya"],answer:0,explain:"Koordinator yang baik membuat tim JELAS & BERGERAK, bukan membuat dirinya paling sibuk atau paling tahu.",hint:"Semua jelas & bergerak, atau koordinator paling sibuk / satu-satunya yang tahu?"},
{n:30,type:"order",micro:"Menyesuaikan peran saat ada anggota tumbang",q:"Urutkan langkah tim saat satu anggota mendadak tidak bisa lanjut (sakit, pindah).",items:["Cari tahu bagian mana yang sudah selesai & mana yang belum","Nilai: bagian yang tersisa mana yang paling kritis untuk hasil?","Bagi ulang bagian tersisa ke anggota yang punya kapasitas, sesuaikan tenggat bila perlu","Perbarui catatan peran & beri tahu semua anggota"],answer:[0,1,2,3],explain:"Inventaris → prioritas → bagi ulang → perbarui & komunikasikan. Jangan panik; tangani sistematis.",hint:"Apa yang perlu diketahui sebelum membagi ulang?"},
{n:31,type:"mcq",micro:"Peran & pengakuan",q:"Saat menilai kontribusi tim secara adil, penting mengingat bahwa...",options:["Kontribusi sama dengan jumlah kata yang diucapkan di rapat, jadi siapa yang paling sering bicara pasti paling banyak berkontribusi","Peran berbeda punya jenis pekerjaan berbeda; kontribusi bukan hanya soal siapa yang tampil atau paling banyak bicara","Hanya peran koordinator yang benar-benar berkontribusi, sedangkan peran lain cuma membantu & tidak perlu dihitung dalam penilaian"],answer:1,explain:"Peneliti yang menydiapkan seluruh data berkontribusi besar meski tidak presentasi. Nilai semua peran.",hint:"Semua jenis pekerjaan dihitung, atau hanya yang tampil?"},
{n:32,type:"tf",micro:"Anggota boleh usul ubah peran",q:"Benar atau Salah: Kalau seorang anggota merasa perannya tidak adil, ia sebaiknya diam & mengerjakannya saja, karena mengeluh soal peran hanya merusak tim.",answer:false,explain:"Sebaliknya, ia berhak menyampaikannya ke tim untuk ditinjau. Peran yang dipaksakan & tak pernah ditinjau menghasilkan anggota frustrasi & hasil buruk.",hint:"Berhak menyampaikan, atau harus diam?"},
{n:33,type:"mcq",micro:"Tanggung jawab meneruskan info",q:"Kamu peran penghubung & menerima info penting dari guru. Tanggung jawabmu:",options:["Menyimpannya dulu sampai rapat berikutnya tiba, supaya semua info bisa disampaikan sekaligus & tidak terlalu sering mengganggu teman","Meneruskannya hanya ke teman-teman dekat di tim saja, lalu membiarkan mereka yang menyampaikan ke anggota lainnya kalau sempat","Meneruskan info itu ke seluruh tim secepatnya & memastikan mereka membacanya"],answer:2,explain:"Peran penghubung gagal kalau info macet di kamu. Teruskan & pastikan diterima.",hint:"Teruskan ke semua secepatnya, atau tahan / pilih-pilih?"},
{n:34,type:"mcq",micro:"Peran & inisiatif",q:"Punya peran spesifik TIDAK berarti kamu...",options:["Tidak boleh menyampaikan ide atau kekhawatiran soal bagian lain — semua anggota tetap boleh berkontribusi pada gambar besar","Boleh mengabaikan semua hal yang ada di luar peranmu, karena itu sepenuhnya bukan urusanmu & sebaiknya kamu tidak berkomentar sedikit pun","Harus meminta izin dulu kepada koordinator sebelum berbicara soal bagian lain, & tidak boleh menyampaikan ide apa pun tanpa persetujuannya"],answer:0,explain:"Peran membagi PEKERJAAN, bukan membungkam SUARA. Semua anggota tetap ikut memikirkan keseluruhan.",hint:"Tetap boleh berkontribusi ke gambar besar, atau bungkam di luar peran?"},
{n:35,type:"mcq",micro:"Peran ganda",q:"Dalam tim kecil (3 orang), wajar bila...",options:["Semua orang harus punya persis satu peran saja, walaupun jumlah pekerjaannya sedikit & beberapa anggota akhirnya tidak punya kerjaan","Satu orang memegang beberapa peran (mis. koordinator + pencatat), asalkan bebannya masih seimbang & jelas","Tim kecil tidak butuh peran sama sekali, karena tiga orang pasti otomatis tahu apa yang harus dikerjakan tanpa perlu dibicarakan"],answer:1,explain:"Jumlah peran menyesuaikan ukuran tim. Yang penting: semua tanggung jawab tercakup & beban adil.",hint:"Peran ganda bila perlu, atau satu peran per orang ketat?"},
{n:36,type:"mcq",micro:"Kejelasan 'selesai'",q:"Untuk tiap peran/tugas, tim sebaiknya menyepakati...",options:["Hanya tenggatnya","Tidak perlu, 'selesai' itu jelas dengan sendirinya","Apa arti 'selesai' untuk bagian itu — standar & bentuk hasilnya seperti apa"],answer:2,explain:"'Selesai' bisa berarti 'draf kasar' bagi satu orang & 'siap kumpul' bagi yang lain. Sepakati definisinya.",hint:"Sepakati arti 'selesai', atau anggap jelas sendiri?"},
{n:37,type:"tf",micro:"Peran bukan status",q:"Benar atau Salah: Peran koordinator tidak membuat seseorang 'lebih penting' atau 'lebih hebat' daripada anggota lain — hanya berbeda tanggung jawab.",answer:true,explain:"Koordinator yang menganggap dirinya 'bos' merusak tim. Semua peran setara nilainya, hanya beda fungsi.",hint:"Peran = status lebih tinggi, atau beda fungsi saja?"},
{n:38,type:"mcq",micro:"Menyerahkan hasil peran",q:"Saat bagianmu selesai, cara menyerahkannya ke tim yang baik:",options:["Beri tahu tim, jelaskan singkat apa isinya & bagaimana memakainya, sebutkan bila ada bagian yang belum yakin","Taruh di folder bersama tanpa memberi tahu siapa pun, lalu biarkan anggota lain mencarinya sendiri & menebak cara memakainya","Kirim hasilnya lalu langsung menghilang tanpa menjelaskan apa-apa, sehingga kalau ada pertanyaan tidak ada yang bisa menjawabnya"],answer:0,explain:"Serah terima yang jelas (apa isinya, cara pakai, catatan) membantu anggota berikutnya melanjutkan tanpa bingung.",hint:"Beri tahu + jelaskan singkat, atau taruh diam-diam?"},
{n:39,type:"mcq",micro:"Peran & tanggung jawab pada tenggat",q:"Kamu pemegang peran yang bagiannya dibutuhkan lebih dulu oleh anggota lain. Ini berarti...",options:["Tenggat tidak berlaku untukmu, karena kamu sudah punya bagian penting & anggota lain yang harus menyesuaikan dirimu bila kamu telat","Tenggatmu lebih ketat — kalau kamu telat, seluruh rantai tim ikut telat; komunikasikan bila ada risiko molor","Kamu bisa santai saja karena hanya memegang 'bagian awal', jadi tidak akan memengaruhi pekerjaan anggota lain kalau selesai terlambat"],answer:1,explain:"Peran di awal rantai memikul tanggung jawab ekstra: keterlambatanmu menggandakan dampaknya ke tim.",hint:"Tenggat lebih ketat karena orang menunggu, atau santai?"},
{n:40,type:"open",micro:"Merancang deskripsi peran",q:"Kamu ketua tim OSIS bidang acara (4 anggota). Buat deskripsi singkat untuk 4 peran: sebutkan nama peran, 2-3 tanggung jawab spesifik tiap peran, dan bagaimana peran-peran itu saling terhubung.",explain:"Jawaban baik menyebut 4 peran yang masuk akal untuk tim acara, masing-masing dengan 2-3 tanggung jawab spesifik (bukan kabur), dan menjelaskan keterhubungan antar peran (mis. output satu peran jadi input peran lain, jadwal induk mengikat semua, siapa perlu koordinasi dengan siapa).",hint:"Nama peran + 2-3 tanggung jawab konkret tiap peran; lalu jelaskan output/input antar peran & apa yang mengikat mereka.",sample:"(1) Koordinator Acara (aku): menyusun rundown & jadwal persiapan, memimpin rapat mingguan, mengecek kemajuan tiap anggota, memutuskan hal mendesak bila tim tidak bisa berkumpul. (2) Penanggung Jawab Pengisi & Susunan: menghubungi & mengonfirmasi pengisi acara/pembicara, menyusun urutan penampilan, menyiapkan naskah MC, memastikan tiap pengisi tahu waktu & durasinya. (3) Penanggung Jawab Teknis & Perlengkapan: mendata kebutuhan (sound, mikrofon, kursi, dekorasi), mengurus peminjaman & pemasangan, menyiapkan rencana cadangan bila alat gagal, hadir lebih awal di hari-H untuk cek teknis. (4) Penanggung Jawab Dokumentasi & Publikasi: membuat poster/pengumuman sebelum acara, mengatur fotografer/perekam saat acara, mengumpulkan & merapikan dokumentasi setelahnya untuk laporan. Keterhubungan: Koordinator memegang jadwal induk yang mengikat ketiga peran lain. PJ Pengisi memberi susunan acara final ke PJ Teknis (supaya tahu kebutuhan sound tiap segmen) dan ke PJ Dokumentasi (supaya tahu momen penting yang harus direkam). PJ Teknis dan PJ Dokumentasi sama-sama perlu hadir paling awal di hari-H. Semua melapor kemajuan ke Koordinator di rapat mingguan."},
{n:41,type:"mcq",micro:"Skenario: tidak ada yang mau jadi koordinator",q:"Di kelompokmu, tidak ada yang mau jadi koordinator. Sikap yang membantu:",options:["Biarkan saja tim tanpa koordinator & berharap semuanya beres sendiri, sebab nanti juga pasti ada orang yang akhirnya turun tangan","Paksa orang yang paling pendiam untuk jadi koordinator, supaya ia belajar berani & anggota lain tidak perlu repot mengurus lagi","Tawarkan diri, atau usulkan koordinasi bergilir per minggu, atau bagi tugas koordinasi (jadwal, cek kemajuan, catatan) ke beberapa orang"],answer:2,explain:"Koordinasi tetap dibutuhkan; kalau tidak ada satu sukarelawan, bagi atau gilir tugas koordinasinya.",hint:"Tawarkan diri / gilir / bagi, atau biarkan / paksa?"},
{n:42,type:"mcq",micro:"Skenario: peran tidak dikerjakan",q:"Pemegang peran pencatat tidak pernah membuat catatan rapat, jadi keputusan sering terlupa. Langkah:",options:["Bicara berdua: ingatkan tanggung jawab perannya & tawarkan bantuan/cara yang lebih mudah; kalau tetap tidak, tim menugaskan orang lain","Diam saja & membiarkan keputusan terus terlupa tiap rapat, karena menegur teman dianggap tidak enak & bisa merusak suasana tim","Menyindirnya di grup chat di depan semua anggota supaya ia malu, lalu berharap ia berubah menjadi pencatat yang lebih rajin"],answer:0,explain:"Peran yang tidak dijalankan perlu ditangani: ingatkan + bantu, lalu tugaskan ulang bila perlu. Bukan didiamkan.",hint:"Ingatkan + bantu, lalu tugaskan ulang — atau diamkan / sindir?"},
{n:43,type:"mcq",micro:"Skenario: kamu diberi peran terlalu besar",q:"Perannya jelas bebannya jauh lebih besar dari peran lain. Sikap:",options:["Kerjakan saja bagianmu seadanya diam-diam supaya beban terasa lebih ringan, tanpa menyampaikan apa pun ke tim soal alasannya sama sekali","Sampaikan ke tim dengan perkiraan konkret ('bagianku kira-kira 10 jam, yang lain 4 jam') & usulkan pemindahan sebagian tugas","Kerjakan semuanya sendiri sambil menyimpan kesal & tidak bilang apa-apa, sampai kamu kelelahan dan hasilnya pun akhirnya ikut menurun"],answer:1,explain:"Ketidakseimbangan yang disuarakan dengan data bisa diperbaiki. Yang dipendam merusak tim & hasil.",hint:"Sampaikan dengan perkiraan + usul pindah, atau pendam / asal?"},
{n:44,type:"mcq",micro:"Skenario: dua orang mau peran yang sama",q:"Dua anggota sama-sama ingin jadi editor video (peran favorit). Cara adil:",options:["Berikan peran itu kepada siapa pun yang paling ngotot & paling lantang memintanya, karena berarti dia yang paling menginginkannya di antara semua","Undi tanpa diskusi apa pun, lalu yang kalah harus menerima hasilnya walaupun kecewa & merasa pengalamannya tidak dipertimbangkan sama sekali","Bagi: satu editor utama, satu asisten editor (belajar + membantu); atau gilir per bagian; diskusikan berdasarkan pengalaman & ketersediaan"],answer:2,explain:"Konflik peran bisa diselesaikan dengan pembagian (utama + asisten), rotasi, atau diskusi berbasis kriteria.",hint:"Bagi utama+asisten / gilir / diskusi kriteria, atau kasih yang ngotot / undi?"},
{n:45,type:"order",micro:"Serah terima antar peran",q:"Urutkan langkah menyerahkan hasil bagianmu ke anggota yang melanjutkannya.",items:["Pastikan bagianmu memenuhi standar 'selesai' yang disepakati tim","Rapikan & beri catatan singkat: apa isinya, format, & bagian yang belum yakin","Beri tahu anggota berikutnya & jelaskan langsung bila perlu","Tetap siap membantu bila ia menemukan masalah dengan bagianmu"],answer:[0,1,2,3],explain:"Penuhi standar → rapikan + catatan → beri tahu & jelaskan → siap bantu. Serah terima yang buruk membuat orang berikutnya tersendat.",hint:"Apa yang dipastikan sebelum menyerahkan?"},
{n:46,type:"mcq",micro:"Skenario: peran berubah di tengah jalan",q:"Di tengah proyek, ternyata bagian desain jauh lebih berat dari perkiraan & bagian riset sudah selesai. Sikap tim:",options:["Tinjau ulang peran: pindahkan si peneliti (yang sudah selesai) untuk membantu desain, sesuaikan tenggat","Biarkan si desainer kewalahan sendirian karena 'itu sudah perannya', sementara si peneliti beristirahat sebab bagiannya memang sudah selesai","Batalkan saja bagian desain supaya tidak merepotkan siapa pun, lalu kumpulkan hasil riset apa adanya tanpa tampilan yang menarik"],answer:0,explain:"Peran melayani proyek. Ketika beban bergeser, tim menyesuaikan siapa membantu di mana.",hint:"Tinjau & pindahkan bantuan, atau biarkan kewalahan?"},
{n:47,type:"mcq",micro:"Skenario: kamu koordinator & ada yang tidak setuju keputusanmu",q:"Sebagai koordinator, kamu membuat keputusan mendesak (tim tidak bisa berkumpul) & seorang anggota tidak setuju. Sikap:",options:["Batalkan semua keputusan yang sudah diambil hanya karena satu orang protes, lalu mulai rapat dari awal sampai semua anggota puas","Jelaskan alasan & konteks keputusanmu; dengarkan keberatannya; kalau masih ada waktu & itu penting, tim bisa meninjau ulang bersama","Bersikeras mempertahankan keputusan karena kamu koordinator & 'punya wewenang', serta tidak mau mendengarkan keberatan apa pun dari siapa pun"],answer:1,explain:"Wewenang koordinator untuk keputusan mendesak tetap disertai keterbukaan menjelaskan & meninjau bila perlu.",hint:"Jelaskan + dengar + tinjau bila perlu, atau bersikeras / batalkan semua?"},
{n:48,type:"mcq",micro:"Skenario: anggota tidak tahu tugasnya",q:"Seminggu berjalan & seorang anggota bertanya 'aku sebenarnya ngerjain apa ya?'. Ini tanda...",options:["Anggota itu bodoh","Tidak masalah, dia bisa menebak sendiri","Pembagian peran di awal kurang jelas atau tidak tertulis; perbaiki sekarang: perjelas & catat tanggung jawabnya"],answer:2,explain:"Kebingungan peran adalah kegagalan proses tim, bukan kegagalan individu. Perbaiki kejelasannya.",hint:"Perjelas & catat peran, atau salahkan orangnya / biarkan menebak?"},
{n:49,type:"mcq",micro:"Skenario: peran pengecek menemukan banyak masalah",q:"Peran pengecek kualitas menemukan bagian seorang anggota banyak yang perlu diperbaiki. Cara menyampaikan:",options:["Berdua, sopan: sebut yang sudah bagus, lalu daftar spesifik yang perlu diperbaiki dengan saran, tawarkan bantuan & waktu","Umumkan daftar kesalahannya di grup supaya semua anggota tahu & ia terdorong memperbaikinya cepat, serta tidak mengulangi kesalahan yang sama","Perbaiki sendiri semuanya diam-diam sambil menyimpan kesal, tanpa memberi tahu pemilik bagian itu bahwa banyak yang perlu diperbaiki"],answer:0,explain:"Peran pengecek adalah membantu tim, bukan mempermalukan. Umpan balik privat, spesifik, dengan saran.",hint:"Berdua + spesifik + saran, atau umumkan / perbaiki diam-diam?"},
{n:50,type:"open",micro:"Skenario menyeluruh: menata ulang tim yang perannya kacau",q:"Kamu bergabung ke tim proyek yang sudah berjalan seminggu tapi kacau: tidak ada yang tahu siapa mengerjakan apa, dua orang membuat bagian yang sama, satu bagian penting terlewat. Sebagai anggota baru, rancang bagaimana kamu membantu menata ulang peran (minimal 5 langkah).",explain:"Jawaban baik: mengusulkan pertemuan dengan nada solusi, membuat daftar lengkap pekerjaan yang terlihat semua, memetakan apa yang sudah dikerjakan untuk menemukan bagian dobel & kosong, menyelesaikan dobel (satu PJ utama) & kosong (tugaskan), menuliskan tabel peran + konfirmasi tiap orang, dan menetapkan cek kemajuan — sambil menyampaikannya sebagai usulan bukan mengambil alih.",hint:"Rapat tanpa menyalahkan → daftar semua pekerjaan → petakan yang sudah dikerjakan → selesaikan dobel & kosong → tabel peran tertulis + konfirmasi → cek kemajuan rutin.",sample:"(1) Usulkan pertemuan singkat seluruh tim dengan nada membantu, bukan menyalahkan: 'Kayaknya kita agak simpang siur soal siapa ngerjain apa. Yuk kita ketemu 20 menit buat rapiin.' (2) Di pertemuan, buat daftar SEMUA pekerjaan yang dibutuhkan proyek di satu tempat yang bisa dilihat semua (papan tulis atau dokumen bersama). (3) Petakan apa yang SUDAH dikerjakan tiap orang sejauh ini ke daftar itu — ini akan menunjukkan bagian yang dobel (dua orang di hal sama) dan bagian yang kosong (terlewat). (4) Untuk bagian yang dobel: sepakati satu orang jadi penanggung jawab utama dan yang satu lagi pindah ke bagian yang kosong atau jadi pendukung. (5) Untuk bagian yang terlewat: tugaskan ke anggota yang punya kapasitas, sesuaikan tenggat bila perlu. (6) Tuliskan hasil akhirnya: tabel 'nama - peran - tanggung jawab spesifik - tenggat' dan bagikan ke semua, minta tiap orang konfirmasi. (7) Sepakati satu jadwal cek kemajuan (mis. tiap 2 hari) supaya kekacauan tidak terulang. Aku menyampaikan semua ini sebagai usulan, bukan mengambil alih, supaya tim tetap merasa memiliki."},
{n:51,type:"mcq",micro:"Skenario: memberi peran ke anggota yang ragu",q:"Seorang anggota berkata 'aku nggak yakin bisa pegang peran itu'. Respons tim yang mendukung:",options:["'Harus bisa dong, nggak ada pilihan lain. Semua orang sudah punya peran & kamu tinggal mengerjakannya saja tanpa banyak alasan.'","'Kami percaya kamu bisa, dan kamu nggak sendirian — [nama] bisa bantu di awal. Kita coba, dan kalau bener-bener nggak cocok kita tinjau lagi.'","'Ya sudah, kalau begitu kamu nggak usah pegang peran apa-apa. Biar kami saja yang mengerjakan semuanya, kamu duduk dan lihat.'"],answer:1,explain:"Dukungan + jaring pengaman + keterbukaan meninjau membantu anggota berani mencoba peran baru.",hint:"Dukungan + bantuan + opsi tinjau, atau lepas tangan / paksa?"},
{n:52,type:"tf",micro:"Deskripsi peran tertulis membantu",q:"Benar atau Salah: Menuliskan deskripsi tiap peran hanya membuang waktu; anggota bisa memahami ekspektasi mereka dari kesepakatan lisan saja.",answer:false,explain:"Sebaliknya, ekspektasi yang tertulis & disepakati (tanggung jawab spesifik + arti 'selesai' + tenggat) mengurangi 'kukira kamu' & 'aku nggak tahu itu bagianku'.",hint:"Deskripsi tertulis membantu, atau tak perlu?"},
{n:53,type:"mcq",micro:"Skenario: koordinator terlalu sibuk",q:"Koordinator kelompokmu kewalahan karena juga mengerjakan bagian besar. Sikap tim:",options:["Biarkan ia kewalahan sendirian karena itu sudah risiko jadi koordinator, & anggota lain cukup fokus mengerjakan bagiannya masing-masing","Ganti koordinator diam-diam tanpa memberi tahu dia, supaya ia tidak sedih dan tim bisa segera mendapat pemimpin yang lebih kuat","Kurangi beban 'mengerjakan tugas'-nya supaya ia bisa fokus mengoordinasi; anggota lain ambil sebagian tugasnya"],answer:2,explain:"Koordinator yang juga pengerja utama sering menjadi hambatan. Kurangi beban tugasnya agar koordinasi jalan.",hint:"Kurangi beban tugasnya, atau biarkan / ganti diam-diam?"},
{n:54,type:"mcq",micro:"Skenario: menghargai peran pendukung",q:"Saat presentasi hasil, cara mengakui peran yang tidak tampil:",options:["Sebut kontribusinya: 'Data & fakta dalam poster ini dikumpulkan & diverifikasi oleh [nama]'","Tidak menyebut siapa pun kecuali yang presentasi, sebab penonton hanya perlu tahu siapa yang berdiri di depan & menjelaskan hasilnya","Klaim semua hasil sebagai hasil kerja presenter sendiri supaya presentasi terdengar meyakinkan, & anggota lain tidak perlu disebutkan"],answer:0,explain:"Pengakuan terbuka atas peran pendukung membuat mereka merasa dihargai & mau berkontribusi lagi.",hint:"Sebut kontribusi mereka, atau abaikan / klaim sendiri?"},
{n:55,type:"mcq",micro:"Skenario: tim tanpa struktur peran",q:"Kelompokmu terbiasa 'kerjakan bareng aja' tanpa peran, & selalu berakhir kacau di menit terakhir. Usulanmu:",options:["Kerjakan sendiri semuanya saja dari awal sampai akhir, supaya tidak kacau lagi di menit terakhir & tak perlu bergantung pada kelompok","'Coba deh kali ini kita bagi peran & tenggat dari awal, terus cek tiap beberapa hari. Kalau nggak enak, balik ke cara lama.'","Ikut cara lama saja karena 'sudah biasa' & toh akhirnya selalu selesai juga walaupun harus lembur dan kacau di menit terakhir"],answer:1,explain:"Mengusulkan struktur sebagai eksperimen ('coba dulu') lebih mudah diterima daripada memaksa perubahan.",hint:"Usulkan bagi peran sebagai coba-coba, atau ikut cara lama / solo?"},
{n:56,type:"mcq",micro:"Skenario: anggota mengambil alih peran orang lain",q:"Seorang anggota diam-diam mengerjakan ulang bagian temannya karena 'kurang bagus', tanpa bilang. Ini...",options:["Bagus sekali, karena hasilnya jadi lebih baik & itulah yang terpenting; perasaan temannya tidak usah dipikirkan dalam pekerjaan tim","Tidak masalah selama dilakukan diam-diam & temannya tidak sampai tahu, sebab dengan begitu tidak akan ada yang tersinggung atau marah","Merusak: temannya merasa tidak dihargai & bingung, kerja jadi ganda; seharusnya beri umpan balik & tawarkan bantuan dulu"],answer:2,explain:"Mengambil alih peran tanpa komunikasi melukai kepercayaan & memboroskan usaha. Umpan balik dulu.",hint:"Merusak kepercayaan & ganda, atau bagus karena hasil lebih baik?"},
{n:57,type:"tf",micro:"Peran & fleksibilitas seimbang",q:"Benar atau Salah: Tim yang baik menyeimbangkan kejelasan peran (semua tahu tanggung jawabnya) dengan fleksibilitas (bersedia membantu di luar peran saat tim butuh).",answer:true,explain:"Terlalu kaku = 'itu bukan bagianku' saat krisis. Terlalu cair = kebingungan & tugas terlewat. Keseimbangan yang menang.",hint:"Kejelasan + fleksibilitas, atau salah satu ekstrem?"},
{n:58,type:"mcq",micro:"Skenario: mengevaluasi peran setelah proyek",q:"Setelah proyek, pertanyaan refleksi tentang peran:",options:["Apakah pembagian peran jelas & adil? Apakah ada peran yang kurang/berlebih? Apa yang akan kita ubah lain kali?","Siapa yang perannya paling gampang & paling sedikit pekerjaannya, supaya lain kali kita bisa memilih peran yang sama lagi dengan mudah","Tidak perlu dibahas sama sekali, sebab peran sudah selesai bersama proyeknya & tidak akan dipakai lagi pada proyek berikutnya"],answer:0,explain:"Meninjau bagaimana pembagian peran berjalan memperbaiki tim untuk proyek berikutnya.",hint:"Refleksi kejelasan & keadilan peran, atau tidak perlu?"},
{n:59,type:"mcq",micro:"Skenario: peran di kegiatan berulang (piket)",q:"Untuk kegiatan rutin seperti piket kelas, sistem peran yang adil:",options:["Anak-anak tertentu selalu yang piket tiap hari, karena mereka dianggap paling rajin & tidak pernah protes ketika diminta mengerjakannya","Jadwal rotasi tertulis yang jelas: siapa, hari apa, tugas apa; dengan cara menukar bila berhalangan","Siapa yang ingat saja yang piket hari itu, tanpa jadwal tertulis, & kalau tidak ada yang ingat maka kelas dibiarkan kotor saja"],answer:1,explain:"Kegiatan berulang butuh sistem peran yang tertulis & bergilir agar adil & tidak ada yang selalu kena/lolos.",hint:"Jadwal rotasi tertulis, atau 'siapa ingat' / orang tertentu selalu?"},
{n:60,type:"open",micro:"Menangani peran yang tak dijalankan",q:"Kamu koordinator. Anggota bernama Fira memegang peran penting (menyiapkan data untuk seluruh tim) tapi sudah lewat tenggat internal 2 hari dan bagiannya belum ada, padahal 3 anggota lain menunggu data itu untuk mulai. Rancang langkahmu.",explain:"Jawaban baik: hubungi pribadi dulu untuk memahami kendala → bantu (pecah tugas, pasangkan, tenggat baru + cek) → kurangi dampak ke tim (anggota lain kerjakan bagian yang tidak bergantung) → siapkan rencana cadangan → catat kronologi faktual → eskalasi ke guru bersama berbasis fakta bila gagal → tanpa gosip / mempermalukan.",hint:"Pahami dulu (hubungi pribadi), bantu, kurangi dampak ke yang menunggu, rencana cadangan, catat fakta, eskalasi bersama sebagai akhir.",sample:"(1) Hubungi Fira secara pribadi dulu, bukan menegur di grup: 'Fira, data yang jadi bagianmu belum masuk dan beberapa teman nunggu itu buat mulai. Ada kendala? Bisa aku bantu?' — cari tahu apa masalahnya (bingung, kesulitan sumber, ada urusan pribadi). (2) Kalau ada kendala nyata: bantu pecah tugasnya jadi lebih kecil, tunjukkan satu-dua sumber untuk memulai, atau pasangkan sementara dengan anggota lain, dan sepakati tenggat baru yang realistis (mis. besok siang) dengan cek di sore ini. (3) Sementara menunggu, kurangi dampak ke tim: minta 3 anggota yang menunggu untuk mengerjakan bagian yang tidak bergantung pada data itu dulu, supaya waktu tidak terbuang. (4) Kalau Fira tetap tidak merespons atau tidak juga bekerja sampai tenggat baru: tim menyiapkan rencana cadangan — data dikerjakan bersama oleh anggota lain, dan porsi Fira dikurangi/dialihkan. (5) Catat kronologinya (kapan tugas dibagi, tenggat, kapan aku menghubungi) secara faktual. (6) Kalau masalah berlanjut & memengaruhi hasil, aku dan tim menemui guru bersama menjelaskan situasi berdasarkan fakta, bukan untuk menjatuhkan Fira tapi supaya proyek bisa selesai dan penilaian adil. (7) Sepanjang proses aku menjaga nada fokus pada solusi & tidak menggosipkan Fira ke anggota lain."},
{n:61,type:"mcq",micro:"Mengapa peran mengurangi konflik",q:"Mengapa peran yang jelas cenderung mengurangi konflik dalam tim?",options:["Karena orang dengan peran yang jelas jadi tidak bicara satu sama lain sama sekali, sehingga tidak ada kesempatan untuk bertengkar","Peran tidak memengaruhi konflik sedikit pun; konflik hanya ditentukan oleh kepribadian orang & tidak ada hubungannya dengan pembagian kerja","Orang tahu batas tanggung jawab masing-masing, jadi lebih sedikit 'kenapa kamu ikut campur bagianku' atau 'kenapa nggak ada yang kerjakan ini'"],answer:2,explain:"Banyak konflik tim lahir dari ambiguitas: siapa yang seharusnya? Kejelasan peran menghapus sebagian besar itu.",hint:"Menghapus ambiguitas 'siapa seharusnya', atau membuat orang diam?"},
{n:62,type:"mcq",micro:"Mengapa fleksibilitas tetap perlu",q:"Mengapa tim yang perannya terlalu kaku ('itu bukan bagianku') bisa gagal?",options:["Saat ada bagian yang jatuh di antara peran, atau satu peran mendadak berat, tidak ada yang mau menutupinya","Karena sikap kaku justru selalu membuat pekerjaan lebih cepat selesai, sehingga tim terburu-buru & melupakan bagian yang harusnya dicek","Kekakuan peran tidak pernah menjadi masalah, sebab semua tugas pasti sudah terpikirkan sejak awal & tidak ada yang tidak terduga"],answer:0,explain:"Realitas proyek berubah. Peran adalah panduan, bukan tembok. Tim butuh orang yang mau melangkah maju saat ada celah.",hint:"Celah antar peran tidak tertutup, atau kaku selalu cepat?"},
{n:63,type:"tf",micro:"Semua peran berkontribusi",q:"Benar atau Salah: Dalam tim yang hasilnya bagus, hampir selalu ada kontribusi nyata dari beberapa peran berbeda — bukan hanya dari satu orang yang 'melakukan semuanya'.",answer:true,explain:"Hasil bagus butuh riset + eksekusi + pengecekan + koordinasi. Satu orang jarang unggul di semuanya sekaligus.",hint:"Kontribusi banyak peran, atau satu orang saja?"},
{n:64,type:"mcq",micro:"Menilai koordinator yang baik",q:"Koordinator yang baik diukur dari...",options:["Seberapa banyak ia memerintah & mengatur anggota lain, karena koordinator yang tegas dianggap pasti membuat tim bekerja lebih baik","Seberapa baik TIM berfungsi (semua jelas, bergerak, terlibat), bukan seberapa banyak koordinator mengerjakan tugas sendiri","Seberapa sibuk koordinator kelihatannya setiap hari, karena koordinator yang selalu sibuk berarti sedang melakukan perannya dengan baik"],answer:1,explain:"Koordinator hebat sering 'tidak terlihat' — timnya berjalan mulus. Yang mengerjakan semua sendiri sebenarnya gagal mengoordinasi.",hint:"Diukur dari fungsi tim, atau kesibukan / perintah koordinator?"},
{n:65,type:"mcq",micro:"Peran & akuntabilitas",q:"Kalau setiap orang bertanggung jawab atas peran spesifik, maka saat sesuatu bermasalah...",options:["Semua orang saling menyalahkan satu sama lain, & masalahnya baru ditangani setelah ditemukan siapa yang paling pantas dipersalahkan","Tidak ada yang perlu bertindak dulu, sebab masalah di dalam tim akan selesai sendiri bila dibiarkan beberapa hari saja tanpa dibahas","Jelas siapa yang perlu menindaklanjuti lebih dulu, sehingga masalah tidak dibiarkan menganggur"],answer:2,explain:"Akuntabilitas peran = 'ini bagianmu, jadi kamu yang memastikan & mengabari'. Tanpa itu, masalah jadi milik 'semua orang' = milik 'tidak seorang pun'.",hint:"Jelas siapa yang menindaklanjuti, atau saling menyalahkan?"},
{n:66,type:"tf",micro:"Koordinator = keputusan mutlak?",q:"Benar atau Salah: Karena koordinator memegang peran koordinasi, semua keputusan tim harus diambil sendiri olehnya tanpa perlu berkonsultasi.",answer:false,explain:"Sebaliknya, koordinator memfasilitasi keputusan bersama; ia boleh memutuskan sendiri hanya untuk hal mendesak yang tidak bisa menunggu tim, dan tetap menjelaskannya.",hint:"Keputusan mutlak sendiri, atau memfasilitasi keputusan bersama?"},
{n:67,type:"mcq",micro:"Peran & pembelajaran",q:"Manfaat merotasi peran antar proyek bagi anggota:",options:["Tiap orang belajar berbagai keterampilan & mengembangkan empati terhadap tantangan tiap peran","Membuat semua orang jadi ahli segalanya dalam semalam","Tidak ada manfaat"],answer:0,explain:"Setelah pernah jadi editor, kamu lebih mengerti kenapa editor butuh materi lebih awal. Rotasi menumbuhkan pemahaman antar peran.",hint:"Belajar keterampilan + empati antar peran, atau tak ada manfaat?"},
{n:68,type:"mcq",micro:"Menilai pembagian peran yang adil",q:"Pembagian peran terasa adil ketika...",options:["Yang paling disukai oleh ketua selalu mendapat peran favorit, sedangkan anggota lain menerima sisanya tanpa boleh menyampaikan pendapat","Beban tiap peran kira-kira sebanding, peran dicocokkan dengan kemampuan sambil memberi ruang belajar, & prosesnya transparan","Semua orang punya peran dengan nama yang sama pentingnya di atas kertas, walaupun beban kerjanya sangat jauh berbeda antar peran"],answer:1,explain:"Keadilan bukan soal nama peran, melainkan soal beban yang sebanding & proses pembagian yang terbuka.",hint:"Beban sebanding + transparan, atau nama peran / favoritisme?"},
{n:69,type:"mcq",micro:"Peran & titik kegagalan tunggal",q:"Kalau hanya satu orang yang tahu cara mengerjakan bagian kritis & ia sakit, tim macet. Cara mencegah:",options:["Berharap orang itu tidak pernah sakit sepanjang proyek, karena bagian yang kritis memang sebaiknya hanya dipegang oleh satu orang ahli saja","Menyalahkan orang itu kalau ia sakit & tidak masuk, supaya lain kali ia lebih menjaga kesehatan dan tidak membuat tim macet lagi","Pastikan minimal dua orang paham bagian kritis, atau dokumentasikan caranya sehingga bisa dilanjutkan orang lain"],answer:2,explain:"Ketergantungan pada satu orang untuk hal kritis adalah risiko. Tim tangguh menyebarkan pengetahuan.",hint:"Sebarkan pengetahuan / dokumentasikan, atau berharap tak sakit?"},
{n:70,type:"order",micro:"Menilai apakah peran perlu ditinjau",q:"Urutkan proses meninjau apakah pembagian peran perlu diubah di tengah proyek.",items:["Amati gejala: ada yang kewalahan? ada bagian yang selalu tersendat? ada yang menganggur?","Kumpulkan pandangan anggota: apakah peran terasa adil & cocok?","Identifikasi penyesuaian: pindahkan bantuan, tukar peran, atau perjelas tanggung jawab","Sepakati perubahan bersama, perbarui catatan, & komunikasikan"],answer:[0,1,2,3],explain:"Amati gejala → tanya anggota → rancang penyesuaian → sepakati & komunikasikan. Peninjauan berbasis bukti & kesepakatan.",hint:"Apa yang diamati sebelum bertanya ke anggota?"},
{n:71,type:"mcq",micro:"Peran & rasa memiliki",q:"Anggota yang punya peran & tanggung jawab yang jelas cenderung...",options:["Merasa lebih memiliki proyek & lebih bertanggung jawab, karena ada bagian yang benar-benar 'milik' mereka","Merasa dibatasi & malas bergerak, sebab peran membuat mereka tidak bebas memilih apa yang dikerjakan setiap hari dalam proyek","Tidak peduli pada hasil akhir, karena bagian mereka sudah jelas & sisanya dianggap bukan urusan mereka lagi dalam proyek tersebut"],answer:0,explain:"Kepemilikan tumbuh dari tanggung jawab yang jelas. 'Bagian ini akuyang pegang' mendorong komitmen.",hint:"Lebih memiliki & bertanggung jawab, atau merasa dibatasi?"},
{n:72,type:"tf",micro:"Peran melayani proyek",q:"Benar atau Salah: Peran ada untuk membantu proyek berhasil & tim bekerja lancar — bukan sebaliknya, di mana proyek dikorbankan demi mempertahankan pembagian peran yang ternyata tidak berjalan.",answer:true,explain:"Kalau sebuah pembagian peran jelas-jelas tidak berfungsi, tim mengubahnya. Peran adalah alat, bukan tujuan.",hint:"Peran melayani proyek, atau proyek melayani peran?"},
{n:73,type:"mcq",micro:"Menilai kontribusi lintas peran",q:"Saat menilai 'siapa berkontribusi paling banyak', kesalahan umum:",options:["Bertanya ke tiap anggota apa saja yang sudah mereka kerjakan, lalu mempertimbangkan semua jenis pekerjaan, baik yang tampil maupun tidak","Hanya menghitung yang terlihat (presentasi, bicara di rapat) & melewatkan kerja peran pendukung (riset, edit, koordinasi, jaga semangat)","Menghitung semua jenis pekerjaan secara adil, termasuk riset, editing, & koordinasi, bukan hanya yang terlihat saat presentasi di depan kelas"],answer:1,explain:"Bias 'yang terlihat = yang berkontribusi' tidak adil bagi peran di belakang layar yang sering justru paling menentukan hasil.",hint:"Hanya menghitung yang terlihat, atau semua jenis kerja?"},
{n:74,type:"mcq",micro:"Peran & konflik ego",q:"Kalau dua anggota berebut peran 'pemimpin' karena gengsi, cara sehat:",options:["Berikan jabatan pemimpin kepada yang paling galak & paling keras suaranya, supaya yang lain segan & tidak ada lagi yang membantah","Buat dua pemimpin yang saling bertentangan, supaya keduanya merasa dihargai & tidak ada yang kalah dalam perebutan jabatan itu","Ingatkan bahwa semua peran setara nilainya & yang penting proyek berhasil; bagi tanggung jawab kepemimpinan atau gilir, fokus pada fungsi bukan gelar"],answer:2,explain:"Konflik peran karena gengsi diselesaikan dengan menggeser fokus dari 'gelar' ke 'fungsi & hasil'.",hint:"Fokus fungsi + bagi/gilir, atau kasih yang galak / dua pemimpin?"},
{n:75,type:"tf",micro:"Peran tertulis = birokrasi berlebihan?",q:"Benar atau Salah: Menuliskan pembagian peran & tanggung jawab, bahkan untuk proyek kecil, umumnya membuang waktu & membuat tim terlalu kaku.",answer:false,explain:"Sebaliknya, catatan singkat 'siapa - apa - kapan' bahkan untuk proyek kecil mencegah banyak salah paham dengan biaya waktu yang sangat kecil.",hint:"Buang waktu & kaku, atau murah & mencegah salah paham?"},
{n:76,type:"mcq",micro:"Peran & anggota baru",q:"Ketika anggota baru bergabung ke tim yang sudah berjalan, hal pertama yang membantunya:",options:["Beri tahu tujuan proyek, peta peran yang ada, & peran/tanggung jawab spesifik untuknya","Biarkan ia mencari tahu sendiri apa yang harus dikerjakan dengan mengamati, karena belajar mandiri itu lebih baik daripada diberi tahu","Beri dia semua tugas yang tidak ada yang mau mengerjakan, karena anggota baru wajib membuktikan dirinya dengan pekerjaan berat dulu"],answer:0,explain:"Orientasi cepat (tujuan + peta peran + peran dia) membuat anggota baru produktif lebih cepat.",hint:"Orientasi tujuan + peta peran + perannya, atau biarkan bingung?"},
{n:77,type:"mcq",micro:"Peran & tanggung jawab pemimpin atas tim",q:"Selain mengoordinasi tugas, koordinator/ketua juga bertanggung jawab...",options:["Tidak bertanggung jawab atas suasana tim sama sekali, sebab tugas koordinator hanya soal pekerjaan & bukan soal perasaan anggota di kelompok","Menjaga semua anggota terlibat & didengar, menangani konflik lebih awal, & memperhatikan anggota yang kesulitan","Hanya soal jadwal & tenggat saja, karena urusan konflik dan perasaan anggota adalah urusan pribadi masing-masing yang tidak perlu dicampuri"],answer:1,explain:"Kepemimpinan tim mencakup sisi manusia: keterlibatan, konflik, & dukungan — bukan hanya logistik.",hint:"Termasuk sisi manusia tim, atau hanya jadwal?"},
{n:78,type:"mcq",micro:"Menilai apakah tim butuh lebih banyak peran",q:"Tanda tim butuh menambah/memperjelas peran:",options:["Semua tugas selesai tepat waktu & rapat berjalan efisien dengan keputusan yang jelas, serta semua anggota tahu apa yang dikerjakan masing-masing","Anggota saling membantu dengan lancar, kualitas terpantau rutin, & tidak ada pekerjaan yang terlewat atau dikerjakan dua orang sekaligus","Sering ada tugas yang terlewat, keputusan rapat terlupa, tidak ada yang memantau kualitas, atau waktu rapat selalu habis tanpa hasil"],answer:2,explain:"Gejala-gejala itu menunjuk peran yang hilang: koordinator, pencatat, pengecek, penjaga waktu.",hint:"Gejala tugas terlewat & rapat kacau, atau semua lancar?"},
{n:79,type:"mcq",micro:"Peran & keadilan penilaian",q:"Kalau guru menilai kelompok, cara agar penilaian mencerminkan kontribusi tiap peran:",options:["Tim bisa menyertakan lampiran pembagian peran + apa yang dikerjakan tiap orang, & bersikap jujur soal kontribusi","Sembunyikan siapa mengerjakan apa supaya tidak ada yang merasa dibeda-bedakan, & serahkan saja hasil akhirnya sebagai karya bersama tanpa keterangan","Semua anggota mengaku mengerjakan segalanya secara merata, walaupun kenyataannya hanya beberapa orang yang bekerja, supaya nilainya sama rata"],answer:0,explain:"Transparansi pembagian peran & kontribusi membantu penilaian yang adil, terutama bila ada perbedaan besar kontribusi.",hint:"Lampirkan pembagian & jujur, atau sembunyikan / semua mengaku semua?"},
{n:80,type:"open",micro:"Menganalisis pembagian peran",q:"Tim A membagi peran hanya sebagai 'kalian berdua bikin isi, kamu bikin desain, aku ketua'. Tim B membagi: 'Rani - riset & tulis bagian sejarah, selesai Selasa; Dito - riset & tulis bagian dampak, selesai Selasa; Sena - desain layout berdasarkan tulisan, draf Kamis; aku - koordinasi, gabungkan Jumat, cek bersama Jumat sore; Rani juga pengecek fakta, Sena juga pengecek tampilan'. Jelaskan minimal 4 kelebihan pembagian Tim B, dan 1 risiko bila Tim B terlalu kaku menerapkannya.",explain:"Jawaban baik menyebut minimal 4 kelebihan Tim B (tanggung jawab spesifik & personal, tenggat internal bertahap sesuai ketergantungan, ada peran pengecek, peran koordinator berfungsi jelas, kemajuan & penilaian lebih adil karena tertulis) dan 1 risiko kekakuan (anggota menolak membantu di luar peran saat beban bergeser).",hint:"Bandingkan spesifik vs kabur, ada tenggat & pengecek vs tidak, koordinator fungsional vs gelar. Lalu risiko: kaku menolak saling bantu.",sample:"Kelebihan Tim B: (1) Tanggung jawab spesifik dan personal — jelas siapa mengerjakan bagian apa (Rani sejarah, Dito dampak), jadi tidak ada 'kukira kamu' seperti di Tim A yang menyuruh 'kalian berdua bikin isi'. (2) Ada tenggat internal per bagian (Selasa, Kamis, Jumat) yang menyusun urutan kerja sesuai ketergantungan (desain menunggu tulisan), sehingga pekerjaan tidak menumpuk di akhir. (3) Ada peran pengecek yang ditunjuk (Rani cek fakta, Sena cek tampilan), jadi kualitas ada yang menjaga — Tim A tidak punya ini. (4) Peran koordinator Tim B jelas fungsinya (koordinasi + gabungkan + jadwalkan cek), bukan sekadar gelar 'ketua' seperti Tim A. (5) Karena semuanya tertulis dan terukur, kemajuan mudah dipantau dan penilaian kontribusi lebih adil. Risiko bila terlalu kaku: kalau Dito selesai lebih dulu dan Rani kewalahan, tapi mereka berpegang bahwa 'itu bukan bagianku', bantuan tidak mengalir dan tim jadi tidak fleksibel. Tim B perlu tetap membuka ruang saling bantu di luar peran saat situasi berubah."},
{n:81,type:"mcq",micro:"Kasus: koordinator yang tidak becus",q:"Koordinator timmu tidak mengoordinasi apa pun — tidak ada jadwal, tidak ada cek, semua bingung. Sebagai anggota, sikap:",options:["Ambil alih koordinasi diam-diam & abaikan koordinator yang ada tanpa bicara, lalu jalankan sistemmu sendiri tanpa memberi tahu siapa pun","Bicara berdua dengan koordinator menawarkan bantuan/cara; kalau tidak berubah, usulkan ke tim agar tugas koordinasi dibagi atau digilir demi menyelamatkan proyek","Diam saja & membiarkan proyek gagal, karena itu memang tanggung jawab koordinator & kamu sebagai anggota biasa tidak boleh ikut campur"],answer:1,explain:"Menyelamatkan proyek bisa dilakukan tanpa 'kudeta': tawarkan bantuan dulu, lalu usulkan berbagi tugas koordinasi secara terbuka.",hint:"Bicara + usulkan bagi tugas terbuka, atau diam / ambil alih diam-diam?"},
{n:82,type:"mcq",micro:"Kasus: kamu diberi peran & juga dituntut hasil bagus",q:"Kamu pemegang peran editor & hasil akhir dinilai dari kualitas editing. Tapi materi dari anggota lain terus telat & berantakan. Sikap:",options:["Terima saja semua materi yang telat & berantakan, lalu tanggung sendiri hasil editing yang buruk tanpa menyampaikan apa-apa pada tim maupun koordinator","Menyerah dan tidak mengedit sama sekali sampai semua materi lengkap, lalu menyalahkan anggota lain di depan guru ketika nilainya jelek","Sampaikan lebih awal ke tim & koordinator bahwa keterlambatan/kualitas materi memengaruhi hasil editing; minta tenggat materi lebih ketat & standar minimum"],answer:2,explain:"Peran di ujung rantai (editor) bergantung pada peran di depannya. Menyuarakan ketergantungan ini lebih awal itu wajar & perlu.",hint:"Suarakan ketergantungan + minta standar & tenggat materi, atau tanggung sendiri / menyerah?"},
{n:83,type:"tf",micro:"Refleksi: peran + fleksibilitas + komunikasi",q:"Benar atau Salah: Tim yang efektif cukup memiliki peran yang jelas saja; kesediaan membantu di luar peran & komunikasi rutin tidak benar-benar diperlukan.",answer:false,explain:"Sebaliknya, ketiganya saling melengkapi: peran memberi kejelasan, fleksibilitas memberi ketahanan, komunikasi rutin menjaga koordinasi.",hint:"Ketiganya bersama, atau salah satu cukup?"},
{n:84,type:"mcq",micro:"Kasus: peran yang tidak dianggap penting",q:"Kamu pemegang peran 'pencatat & perapi format' & seorang anggota berkata 'itu peran gampang, nggak ngapa-ngapain'. Sikap:",options:["Jelaskan dengan tenang apa yang sebenarnya kamu kerjakan & nilainya (catatan mencegah keputusan terlupa, format rapi mengangkat nilai); kalau bebannya memang ringan, tawarkan mengambil tugas tambahan","Tersinggung lalu berhenti mengerjakan catatan & format sama sekali, supaya mereka merasakan sendiri akibat dari meremehkan perannya itu","Mengiyakan saja bahwa perananmu memang tidak penting & merasa tidak berharga, lalu mengerjakan seadanya tanpa semangat lagi pada proyek ini"],answer:0,explain:"Jelaskan nilai perannya; bila memang bebannya ringan dibanding lain, seimbangkan dengan mengambil lebih. Peran pendukung tetap berharga.",hint:"Jelaskan nilainya + seimbangkan beban, atau tersinggung / merendah?"},
{n:85,type:"order",micro:"Onboarding anggota baru ke peran",q:"Urutkan langkah memasukkan anggota baru ke sebuah peran di tim yang sedang berjalan.",items:["Jelaskan tujuan proyek & status saat ini secara singkat","Tunjukkan peta peran: siapa mengerjakan apa","Jelaskan peran & tanggung jawab spesifik untuknya, termasuk arti 'selesai' & tenggat","Pasangkan dengan satu anggota sebagai tempat bertanya di minggu pertama"],answer:[0,1,2,3],explain:"Tujuan & status → peta peran → perannya sendiri → mentor sementara. Anggota baru jadi produktif tanpa banyak menebak.",hint:"Apa yang dijelaskan sebelum peran spesifiknya?"},
{n:86,type:"mcq",micro:"Kasus: peran berubah karena kekuatan tersembunyi",q:"Di tengah proyek, ternyata anggota yang dikira 'kurang bisa' punya keterampilan yang sangat dibutuhkan (mis. jago bikin grafik). Sikap tim:",options:["Bebani dia dengan semua pekerjaan grafik tanpa bertanya apakah ia mau & sanggup, karena ia satu-satunya yang jago melakukannya di tim","Sesuaikan peran untuk memanfaatkan kekuatan itu, dengan persetujuannya, & seimbangkan ulang tugas lain","Biarkan saja seperti semula, sebab peran sudah terlanjur dibagi di awal & mengubahnya hanya akan membuat tim bingung & membuang waktu"],answer:1,explain:"Peran sebaiknya menyesuaikan diri dengan kekuatan yang ditemukan, selama anggota setuju & bebannya tetap adil.",hint:"Sesuaikan peran dengan persetujuan, atau biarkan / bebani sepihak?"},
{n:87,type:"tf",micro:"Peran & tanggung jawab tidak menghapus empati",q:"Benar atau Salah: Meskipun tiap orang bertanggung jawab atas perannya, tim tetap perlu peka bila seorang anggota sedang kesulitan (pribadi atau teknis) & menyesuaikan dukungan, bukan sekadar menuntut 'itu kan tanggung jawabmu'.",answer:true,explain:"Akuntabilitas & empati berjalan bersama. Tim yang hanya menuntut tanpa mendukung akan kehilangan anggota & semangat.",hint:"Tuntut saja, atau tuntut + dukung?"},
{n:88,type:"mcq",micro:"Kasus: kamu ingin peran yang lebih menantang",q:"Kamu selalu diberi peran 'aman' & ingin mencoba peran yang lebih menantang untuk belajar. Sikap:",options:["Ambil peran itu diam-diam tanpa memberi tahu tim, supaya tidak ada yang melarang atau meragukan kemampuanmu, lalu tunjukkan hasilnya nanti","Menunggu terus sampai ada yang menawarimu peran itu, sebab meminta sendiri dianggap tidak sopan & bisa membuat anggota lain merasa terganggu","Sampaikan ke tim: 'Aku pengin coba pegang [peran] kali ini buat belajar. Aku siap dibimbing & kalau mepet aku minta bantuan.'"],answer:2,explain:"Menyuarakan keinginan belajar + menawarkan komitmen & kerendahan hati membuat tim lebih mungkin memberimu kesempatan.",hint:"Sampaikan + tawarkan komitmen, atau ambil diam-diam / menunggu?"},
{n:89,type:"mcq",micro:"Kasus: tanggung jawab saat semua peran gagal",q:"Proyek gagal & tiap peran punya andil kegagalan (riset dangkal, desain telat, koordinasi lemah). Sikap tim yang matang saat refleksi:",options:["Tiap orang mengakui bagian andilnya secara jujur & tim merancang perbaikan sistem (tenggat, cek, standar) untuk lain kali","Menunjuk satu orang sebagai penyebab utama kegagalan di depan semua anggota, lalu mengganti dia dengan orang lain di proyek berikutnya","Menyimpulkan 'kita memang tim yang buruk' & menyerah, karena kegagalan berarti tim ini tidak mungkin berhasil bekerja sama pada kesempatan lain"],answer:0,explain:"Kegagalan yang melibatkan banyak peran butuh pengakuan bersama & perbaikan sistem, bukan kambing hitam atau penyerahan.",hint:"Akui andil masing-masing + perbaiki sistem, atau kambing hitam / menyerah?"},
{n:90,type:"open",micro:"Kasus menyeluruh",q:"Kamu akan memimpin tim 6 orang untuk lomba yang berlangsung 4 minggu, dengan anggota yang kemampuannya beragam (2 sangat terampil, 2 sedang, 2 kurang percaya diri). Rancang bagaimana kamu membagi & mengelola peran agar: hasil kompetitif, semua anggota terlibat & berkembang, dan tim tetap solid. Minimal 6 keputusan konkret dengan alasan.",explain:"Jawaban baik memuat minimal 6 keputusan konkret dengan alasan: petakan pekerjaan lalu bagi inti vs pendukung, pasangkan terampil + belajar (mentor-asisten), beri yang kurang PD tanggung jawab jelas & terbatas yang bisa dibanggakan, tuliskan peran + tenggat + konfirmasi, cek kemajuan rutin termasuk memantau pasangan mentor, rotasi/latihan nyata untuk asisten, kepemimpinan melayani + apresiasi spesifik, refleksi. Menyeimbangkan hasil kompetitif + keterlibatan/perkembangan semua + solidaritas.",hint:"Seimbangkan tiga tujuan: hasil (yang terampil di peran inti), perkembangan (pasangan mentor-asisten + rotasi), solidaritas (tanggung jawab jelas untuk semua + apresiasi + cek rutin + refleksi).",sample:"(1) Petakan dulu semua pekerjaan lomba, lalu bagi jadi peran inti (butuh keterampilan tinggi) dan peran pendukung (bisa dipelajari sambil jalan). Alasan: supaya pembagian berbasis kebutuhan nyata, bukan tebakan. (2) Tempatkan 2 anggota terampil di peran inti, tapi PASANGKAN masing-masing dengan satu anggota sedang/kurang PD sebagai 'asisten yang belajar'. Alasan: hasil tetap kuat karena dipegang yang terampil, sekaligus yang lain belajar langsung dan merasa dilibatkan. (3) Beri 2 anggota kurang percaya diri satu tanggung jawab pendukung yang jelas, terbatas, dan penting (mis. riset data + cek fakta, atau dokumentasi + logistik) — sesuatu yang bisa mereka kuasai dan banggakan. Alasan: keberhasilan di tugas yang terdefinisi jelas membangun kepercayaan diri. (4) Tuliskan semua peran + tanggung jawab spesifik + tenggat internal (selesai 3 hari sebelum batas) di dokumen bersama, minta tiap orang konfirmasi. Alasan: kejelasan & rasa memiliki. (5) Rapat cek kemajuan 2x seminggu (20 menit): tiap orang lapor + kendala; aku mengecek pasangan mentor-asisten berjalan baik. Alasan: menemukan masalah & ketimpangan lebih awal. (6) Rotasi kecil di minggu ke-3: minta asisten mengerjakan satu bagian inti kecil sendiri dengan pengawasan, supaya mereka benar-benar berlatih, bukan hanya menonton. Alasan: perkembangan nyata. (7) Sebagai pemimpin, aku memimpin dengan melayani: memfasilitasi, mengapresiasi kontribusi tiap orang secara spesifik & terbuka, menangani konflik lebih awal, dan turun membantu bagian yang tertinggal. Alasan: tim meniru sikap pemimpin & semangat menentukan hasil. (8) Refleksi tengah & akhir: apa yang berjalan, apa yang perlu diubah, apresiasi bersama."},
{n:91,type:"mcq",micro:"Kasus: peran vs pertemanan",q:"Sahabatmu di tim tidak menjalankan perannya & berharap kamu 'menutupi' karena kalian teman. Sikap:",options:["Langsung melaporkannya ke guru tanpa bicara dulu dengannya, sebab persahabatan tidak boleh memengaruhi urusan pekerjaan sama sekali di dalam tim","Bantu sekali sebagai teman bila darurat, tapi sampaikan jujur bahwa ini tidak bisa terus & tim butuh ia menjalankan perannya","Selalu menutupi kekurangannya setiap kali, karena kalian sahabat & sahabat sejati pasti saling melindungi apa pun yang terjadi kepada yang lain"],answer:1,explain:"Pertemanan tidak boleh menjadi alasan satu orang lepas dari tanggung jawab tim. Bantu sekali, lalu jujur.",hint:"Bantu sekali + jujur, atau selalu menutupi / langsung lapor?"},
{n:92,type:"tf",micro:"Refleksi: peran adalah kesepakatan, bukan perintah",q:"Benar atau Salah: Pembagian peran yang paling berhasil adalah yang disepakati bersama (dengan masukan tiap anggota tentang kekuatan & ketersediaannya), bukan yang ditetapkan sepihak lalu dipaksakan.",answer:true,explain:"Anggota yang ikut menentukan perannya merasa lebih memiliki & lebih berkomitmen daripada yang sekadar ditugaskan.",hint:"Disepakati bersama, atau ditetapkan sepihak?"},
{n:93,type:"mcq",micro:"Kasus: peran koordinator dirotasi",q:"Timmu memutuskan merotasi peran koordinator tiap minggu. Yang membuat ini berhasil:",options:["Tiap koordinator baru mengubah semua sistem kerja sesukanya begitu menjabat, supaya terasa ada perubahan & ia merasa punya kendali penuh atas timnya","Tidak ada serah terima sama sekali; koordinator baru dibiarkan menebak sendiri apa yang sudah terjadi, & anggota lain tidak perlu menjelaskan apa-apa","Serah terima yang jelas tiap pergantian (status, tugas berjalan, catatan), & format kerja yang konsisten sehingga koordinator baru tidak mulai dari nol"],answer:2,explain:"Rotasi peran butuh proses serah terima yang rapi & konsistensi sistem agar tidak kacau tiap pergantian.",hint:"Serah terima jelas + sistem konsisten, atau tiap orang ubah semua / menebak?"},
{n:94,type:"mcq",micro:"Kasus: menilai kontribusi untuk penilaian diri/teman",q:"Guru meminta tiap anggota menilai kontribusi anggota lain. Cara yang adil & jujur:",options:["Nilai berdasarkan bukti (bagian yang dikerjakan, keandalan, keterlibatan), pertimbangkan semua jenis peran, & jujur meski itu teman/bukan teman","Beri semua orang nilai maksimal supaya aman & tidak ada yang tersinggung, walaupun kenyataannya kontribusi tiap anggota berbeda jauh satu sama lain","Beri nilai rendah kepada anggota yang tidak kamu sukai & nilai tinggi kepada sahabat-sahabatmu, karena kamu paling tahu perilaku mereka sehari-hari"],answer:0,explain:"Penilaian sebaya yang berguna berbasis kontribusi nyata & jujur, bukan berdasarkan suka/tidak suka atau menghindari konflik.",hint:"Berbasis bukti & jujur, atau semua maksimal / berdasarkan suka?"},
{n:95,type:"tf",micro:"Peran memberi kejelasan, bukan sekat",q:"Benar atau Salah: Setelah peran dibagi, anggota sebaiknya tidak lagi mengusulkan ide atau ikut memikirkan bagian di luar perannya sendiri.",answer:false,explain:"Sebaliknya, peran membagi pekerjaan, bukan membatasi kepedulian atau suara. Anggota tetap boleh membantu, mengusulkan ide, & memikirkan gambar besar.",hint:"Kejelasan tanpa tembok, atau sekat yang membatasi?"},
{n:96,type:"mcq",micro:"Kasus: refleksi peranmu sendiri",q:"Cara melatih dirimu jadi pemegang peran yang lebih andal:",options:["Tidak pernah mengevaluasi peranmu sendiri setelah proyek berakhir, karena yang penting hasilnya sudah dikumpulkan & mendapat nilai yang cukup baik","Setelah tiap proyek: apakah aku menepati tanggung jawab peranku? mengabari kendala tepat waktu? membantu di luar peran saat perlu? apa satu hal yang akan kuperbaiki?","Menyimpulkan bahwa peran milik orang lain jauh lebih mudah daripada perannya sendiri, jadi wajar kalau kamu tidak bisa menjalankannya dengan sempurna"],answer:1,explain:"Menilai seberapa baik kamu menjalankan peranmu (keandalan, komunikasi, fleksibilitas) mempercepat kamu jadi anggota tim yang dipercaya.",hint:"Evaluasi keandalan peranmu, atau membandingkan / tak pernah?"},
{n:97,type:"mcq",micro:"Prinsip inti bab ini",q:"Pesan inti peran & tanggung jawab dalam tim:",options:["Berikan semua peran penting kepada satu orang terpintar di kelompok supaya cepat selesai & tidak ribet; anggota lain cukup mengikuti arahannya dan tidak perlu banyak bertanya","Jangan pernah membagi peran secara tertulis, kerjakan semuanya bersama-sama setiap saat; kalau ada masalah, dibahas saja kalau sempat dan tenggat sudah dekat sekali","Bagi pekerjaan jadi peran yang jelas & tertulis (tanggung jawab spesifik + arti 'selesai' + tenggat), cocokkan dengan kekuatan sambil beri ruang belajar, seimbangkan beban, sepakati bersama, tetap fleksibel & berkomunikasi, dan hargai semua peran setara"],answer:2,explain:"Ringkasan: peran jelas & tertulis + cocok kekuatan + beban seimbang + disepakati + fleksibel + komunikasi + semua peran dihargai.",hint:"Jelas & tertulis, cocok kekuatan, seimbang, disepakati, fleksibel, komunikasi, dihargai setara — rangkai."},
{n:98,type:"tf",micro:"Refleksi: peran untuk tim & individu",q:"Benar atau Salah: Pembagian peran yang baik menguntungkan tim (pekerjaan tercakup & terkoordinasi) DAN tiap individu (tahu ekspektasi, punya bagian yang dimiliki, & kesempatan berkembang).",answer:true,explain:"Peran yang dirancang baik melayani dua tingkat sekaligus: efektivitas tim & pertumbuhan serta kejelasan bagi tiap orang.",hint:"Untung tim & individu, atau tim saja?"},
{n:99,type:"mcq",micro:"Kasus: memulai memperbaiki cara timmu membagi peran",q:"Cara termudah mulai memperbaiki pembagian peran di kelompok berikutnya:",options:["Di pertemuan pertama, usulkan menghabiskan 15 menit untuk: daftar pekerjaan, cocokkan dengan orang, tulis 'siapa - apa - kapan', konfirmasi bersama","Menunggu sampai bertemu kelompok yang lebih terorganisasi & punya ketua yang tegas, baru kemudian mulai memikirkan pembagian peran secara serius dengan mereka","Membiarkan pembagian peran terjadi sendiri secara alami seiring pekerjaan berjalan, tanpa dibahas, ditulis, atau dikonfirmasi oleh siapa pun di dalam kelompok"],answer:0,explain:"Investasi 15 menit di awal untuk kejelasan peran menghemat berjam-jam kebingungan & konflik nanti.",hint:"15 menit membagi peran di awal, atau menunggu / membiarkan?"},
{n:100,type:"open",micro:"Refleksi & aturan pribadi soal peran",q:"Tulis 'aturan pribadi tentang peran & tanggung jawab dalam tim' berisi minimal 5 poin yang akan kamu pegang, masing-masing dengan alasan singkat.",explain:"Jawaban baik memuat minimal 5 aturan konkret dengan alasan, mencakup ide inti bab: pastikan peran tertulis & disepakati di awal, perjelas arti 'selesai', jalankan tanggung jawab tanpa diingatkan + kabari kendala dini, fleksibel membantu di luar peran, suarakan bila peran tidak adil/cocok untuk ditinjau, hargai semua peran setara & akui kontribusi, (bila koordinator) memimpin dengan melayani.",hint:"Ambil satu pelajaran tiap fase — tulis & sepakati peran, perjelas 'selesai', akuntabilitas + kabari kendala, fleksibel, suarakan ketidakadilan, hargai semua peran, memimpin melayani — jadikan aturan 'aku akan...'.",sample:"Contoh aturan pribadi: (1) Di awal proyek, aku ikut memastikan kami membuat daftar pekerjaan & menuliskan 'siapa - peran - tanggung jawab spesifik - tenggat' yang disepakati semua — karena kejelasan tertulis mencegah 'kukira kamu'. (2) Aku memperjelas arti 'selesai' untuk bagianku sebelum mulai — karena 'selesai' berarti beda bagi tiap orang. (3) Aku menjalankan tanggung jawab peranku tanpa harus diingatkan terus, dan bila ada risiko molor aku mengabari tim lebih awal — karena akuntabilitas berarti aku yang memastikan & mengabari. (4) Aku bersedia membantu di luar peranku saat tim butuh atau saat ada bagian yang jatuh di celah — karena peran memberi kejelasan, bukan alasan berkata 'bukan bagianku'. (5) Kalau perannku terasa tidak adil bebannya atau tidak cocok, aku menyampaikannya ke tim dengan data untuk ditinjau — bukan memendam atau mengerjakan asal. (6) Aku menghargai semua peran setara, termasuk yang di belakang layar, dan menyebut kontribusi orang lain saat menilai atau presentasi — karena hasil bagus butuh semua peran. (7) Sebagai koordinator, aku memimpin dengan melayani: memfasilitasi, memastikan semua terlibat & tahu tugasnya, bukan memerintah atau mengerjakan semua sendiri."},
];
